const fields = ['location_id','date','model',...essentialFields,'relative_humidity_mean_pct','apparent_temperature_mean_c','cloud_cover_mean_pct','sunshine_duration_hours','wind_gust_max_kmh','precipitation_hours','wind_direction_dominant_deg','dew_point_mean_c','shortwave_radiation_mj_m2','latitude','longitude']
