const chartTitles:Record<string,string> = {bar:'Monthly precipitation comparison',line:'Historical climate trends',year_compare:'Year-by-year temperature comparison',box:'Daily climate distributions',bubble:'Temperature and rainfall',rain_wind:'Rainfall and wind speed',heatmap:'Seasonal rainfall heatmap',mosaic:'Rainy and dry days',treemap:'Rainy-day hierarchy',map:'Climate map',temp_solar:'Temperature vs solar radiation',rain_solar:'Rainfall vs solar radiation',temp_compare:'Temperature source comparison',solar_seasonal:'Seasonal solar radiation',multi_correlation:'Multivariate climate correlation',solar_map:'Solar radiation map',annual_solar:'Annual solar radiation trend',cloud_solar:'Cloud cover vs solar radiation',humidity_compare:'Humidity source comparison',annual_rain:'Annual rainfall trend',rain_year_month:'Month-by-year rainfall',coverage:'Observation coverage',hot_days:'Temperature extremes',strong_wind_days:'Wind extremes',temperature_range:'Daily temperature range',temperature_humidity:'Temperature vs humidity',rain_duration:'Rainfall vs duration'}
const day = (value:string) => Math.floor(Date.parse(value+'T00:00:00Z')/86400000)
const iso = (value:number) => new Date(value*86400000).toISOString().slice(0,10)
const show = (value:unknown) => value === null || value === undefined ? '—' : typeof value === 'number' ? Number.isInteger(value) ? String(value) : value.toFixed(2) : String(value)

async function limited<T>(jobs:(()=>Promise<T>)[], concurrency:number):Promise<T[]>{
  const output:T[] = new Array(jobs.length)
  let next = 0
  await Promise.all(Array.from({length:Math.min(concurrency,jobs.length)},async()=>{
    while(next<jobs.length){const index=next++;output[index]=await jobs[index]()}
  }))
  return output
}

function ChartView({result,compact=false}:{result:Result;compact?:boolean}) {
  const plot=useRef<HTMLDivElement>(null)
  useEffect(()=>{if(result.figure.type!=='plotly'||!plot.current)return;let active=true;const node=plot.current;import('plotly.js-dist-min').then(({default:Plotly})=>{if(active)Plotly.newPlot(node,result.figure.content.data,result.figure.content.layout,{responsive:true,displaylogo:false})});return()=>{active=false;import('plotly.js-dist-min').then(({default:Plotly})=>Plotly.purge(node))}},[result])
  if(result.figure.type==='png')return <img className="chart-image" src={'data:image/png;base64,'+result.figure.content} alt={chartTitles[result.chart_id]+' generated in Python'}/>
  if(result.figure.type==='html')return <MapView result={result} compact={compact}/>
  return <div className="plotly-frame" ref={plot} role="img" aria-label="Interactive rainy-day treemap"/>
}

function EvidenceTable({result}:{result:Result}) {
  return <div className="evidence-scroll"><table><thead><tr>{result.supporting_columns.map(c=><th key={c}>{c.replaceAll('_',' ')}</th>)}</tr></thead><tbody>{result.supporting_data.map((row,i)=><tr key={i}>{result.supporting_columns.map(c=><td key={c}>{show(row[c])}</td>)}</tr>)}</tbody></table></div>
}

function DetailModal({modal,onClose,onDownload,downloading}:{modal:Modal;onClose:()=>void;onDownload:(r:Result,kind:'data'|'package'|'script')=>void;downloading:boolean}) {
  const [codeTab,setCodeTab]=useState<'Visualization Code'|'Data Preparation'|'Topic Notes'>('Visualization Code')
  useEffect(()=>setCodeTab('Visualization Code'),[modal?.result.analysis_id,modal?.kind])
  if(!modal)return null
  const r=modal.result
  const code=codeTab==='Visualization Code'?r.python_source.visualization:r.python_source.preparation
  return <Dialog.Root open onOpenChange={open=>{if(!open)onClose()}}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="dialog-content" aria-describedby="modal-description">
    <div className="dialog-top"><div><span className="eyebrow">{r.python_source.topic.chapter} · {r.python_source.topic.topic}</span><Dialog.Title>{modal.kind==='code'?'Show Python Code':modal.kind==='interpretation'?'Data Interpretation':'View Data'}</Dialog.Title><p id="modal-description">{r.renderer} · {r.units} · {r.sample_size} chart-input rows · {r.sources.join(' / ')}</p></div><Dialog.Close className="icon-button" aria-label="Close dialog"><X size={20}/></Dialog.Close></div>
    <div className="dialog-body"><div className="dialog-visual"><ChartView result={r} compact/><div className="dialog-meta"><span>Locations: {((r.filters.locations as string[])||[]).join(', ')||'All loaded locations'}</span><span>{String(r.filters.start_date||'first record')} – {String(r.filters.end_date||'last record')}</span></div>{r.limitations.map((x,i)=><p className="caveat" key={i}><Info size={14}/>{x}</p>)}</div>
    <div className="dialog-side">{modal.kind==='code'?<><div className="segmented" role="tablist">{(['Visualization Code','Data Preparation','Topic Notes'] as const).map(t=><button key={t} role="tab" aria-selected={codeTab===t} className={codeTab===t?'selected':''} onClick={()=>setCodeTab(t)}>{t}</button>)}</div>{codeTab==='Topic Notes'?<div className="notes"><h3>{r.python_source.topic.topic}</h3><p>{r.python_source.topic.objective}</p><p><strong>Actual function:</strong> <code>{r.python_source.topic.library_function}</code></p><p>The displayed source is read from the Python builder that generated this result.</p></div>:<><div className="code-scroll"><Highlight theme={themes.nightOwl} code={code.trim()} language="python">{({className,style,tokens,getLineProps,getTokenProps})=><pre className={className} style={style}>{tokens.map((line,i)=><div key={i} {...getLineProps({line})} className={r.python_source.highlights.some(h=>line.map(t=>t.content).join('').includes(h))?'teaching-line':''}><span className="line-no">{i+1}</span>{line.map((token,j)=><span key={j} {...getTokenProps({token})}/>)}</div>)}</pre>}</Highlight></div><div className="dialog-actions"><button onClick={()=>navigator.clipboard.writeText(code)}><Code2 size={16}/> Copy Code</button><button onClick={()=>onDownload(r,'script')} disabled={downloading}><FileCode2 size={16}/> Download Python Script</button><button onClick={()=>onDownload(r,'package')} disabled={downloading}><ArrowDownToLine size={16}/> Download Reproduction Package</button></div></>}</>:modal.kind==='interpretation'?<div className="interpretation"><span className="status-pill">{r.computed_facts.label}</span><h3>Visualization Overview</h3><p>{r.computed_facts.shows}</p><h3>Statistical Findings</h3><p>{r.computed_facts.findings}</p><h3>Relationship Analysis</h3><p>{r.statistics?.pearson_r===undefined?'Compare observations within the same selected period and location.':r.statistics.pearson_r===null?'Correlation is unavailable with these observations.':'Pearson r = '+r.statistics.pearson_r.toFixed(3)+' from '+r.statistics.paired_observations+' paired observations. This does not establish causation.'}</p><h3>Geographic or Seasonal Implications</h3><p>{r.computed_facts.relevance}</p><h3>Limitations</h3>{r.computed_facts.limitations.map((x,i)=><p key={i}>{x}</p>)}<h3>Evidence Table</h3><EvidenceTable result={r}/></div>:<><h3>Supporting data</h3><p>First 30 rows shown. Download the full chart-input table.</p><EvidenceTable result={r}/><button className="primary small" onClick={()=>onDownload(r,'data')}><ArrowDownToLine size={16}/> Download CSV</button></>}</div></div>
  </Dialog.Content></Dialog.Portal></Dialog.Root>
}

function SummaryCodeModal({item,onClose,onDownload}:{item:{source:string;preparation:string;summary:Summary}|null;onClose:()=>void;onDownload:(kind:'package'|'script')=>void}) {
  const [section,setSection]=useState<'Calculation Code'|'Period Preparation'>('Calculation Code')
  if(!item)return null
  const code=section==='Calculation Code'?item.source:item.preparation
  return <Dialog.Root open onOpenChange={open=>{if(!open)onClose()}}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="dialog-content" aria-describedby="summary-code-description"><div className="dialog-top"><div><span className="eyebrow">CLIMATE OVERVIEW · PYTHON CALCULATION</span><Dialog.Title>Show Python Code</Dialog.Title><p id="summary-code-description">Selected {item.summary.selected_period.join(' to ')} · {item.summary.source}</p></div><Dialog.Close className="icon-button" aria-label="Close dialog"><X size={20}/></Dialog.Close></div><div className="dialog-body"><div className="dialog-visual"><h3>Current calculated indicators</h3><div className="summary-modal-values"><span>Mean temperature: {show(item.summary.mean_temperature_c)} °C</span><span>Precipitation: {show(item.summary.total_precipitation_mm)} mm at one location</span><span>Rainy-day frequency: {show(item.summary.rainy_day_frequency_pct)}%</span><span>Maximum wind: {show(item.summary.maximum_wind_kmh)} km/h</span><span>Valid temperature: {item.summary.valid_observations} days</span><span>Reference period: {item.summary.anomaly_reference_period.join(' to ')}</span></div><p className="caveat">The package includes the exact filtered daily input, reference observations, Python functions, and a runnable script.</p></div><div className="dialog-side"><div className="segmented"><button className={section==='Calculation Code'?'selected':''} onClick={()=>setSection('Calculation Code')}>Calculation Code</button><button className={section==='Period Preparation'?'selected':''} onClick={()=>setSection('Period Preparation')}>Period Preparation</button></div><div className="code-scroll"><Highlight theme={themes.nightOwl} code={code.trim()} language="python">{({className,style,tokens,getLineProps,getTokenProps})=><pre className={className} style={style}>{tokens.map((line,i)=><div key={i} {...getLineProps({line})} className={line.map(t=>t.content).join('').includes('groupby')||line.map(t=>t.content).join('').includes('mean(')||line.map(t=>t.content).join('').includes('std(')?'teaching-line':''}><span className="line-no">{i+1}</span>{line.map((token,j)=><span key={j} {...getTokenProps({token})}/>)}</div>)}</pre>}</Highlight></div><div className="dialog-actions"><button onClick={()=>navigator.clipboard.writeText(code)}><Code2 size={16}/> Copy Code</button><button onClick={()=>onDownload('script')}><FileCode2 size={16}/> Download Python Script</button><button onClick={()=>onDownload('package')}><ArrowDownToLine size={16}/> Download Reproduction Package</button></div></div></div></Dialog.Content></Dialog.Portal></Dialog.Root>
}

function ChartCard({chart,result,error,loading,yearControl,onOpen,onDownload}:{chart:Chart;result?:Result;error?:string;loading:boolean;yearControl?:{value:string;years:number[];onChange:(year:string)=>void};onOpen:(kind:'code'|'interpretation'|'data',r:Result)=>void;onDownload:(r:Result,kind:'data'|'package'|'script')=>void}) {
  const [selectedMonth,setSelectedMonth]=useState('')
  useEffect(()=>setSelectedMonth(''),[result?.analysis_id])
  const monthRow=selectedMonth&&result?.chart_id==='rain_year_month'?result.supporting_data[Number(selectedMonth)-1]:null
  return <article className="chart-card"><div className="chart-card-head"><div><div className="badge-row"><span className="chapter-badge">{chart.chapter}</span><span className="topic-badge">{chart.topic}</span></div><h3>{chartTitles[chart.id]||chart.topic}</h3><p>{chart.objective}</p>{yearControl&&<label className="chart-year-control">Show year <select aria-label="Monthly precipitation year" value={yearControl.value} onChange={e=>yearControl.onChange(e.target.value)} disabled={loading}><option value="">All years (monthly average)</option>{yearControl.years.map(year=><option key={year} value={year}>{year}</option>)}</select></label>}</div><span className="renderer-label">{result?.renderer||chart.function}</span></div>{loading?<div className="chart-placeholder"><div className="spinner"/> Preparing Python analysis…</div>:result?<><div className="chart-stage"><ChartView result={result}/></div>{result.chart_id==='rain_year_month'&&<div className="month-inspector"><label>Inspect a month<select aria-label="Inspect rainfall month" value={selectedMonth} onChange={e=>setSelectedMonth(e.target.value)}><option value="">Select location and month</option>{result.supporting_data.map((row,i)=><option key={i} value={i+1}>{show(row.location_name)} · {show(row.year)}-{String(row.month).padStart(2,'0')}</option>)}</select></label>{monthRow&&<p>{show(monthRow.location_name)}, {show(monthRow.year)}-{String(monthRow.month).padStart(2,'0')}: {show(monthRow.precipitation_mm)} mm · {show(monthRow.precipitation_valid_days)} of {show(monthRow.expected_days)} valid days · {show(monthRow.period_status)}</p>}</div>}<div className="chart-detail"><span>{result.units}</span><span>{result.sample_size} chart-input rows</span><span>{result.sources[0]}</span>{result.statistics?.pearson_r!==undefined&&<span>Pearson r: {result.statistics.pearson_r===null?'unavailable':result.statistics.pearson_r.toFixed(3)}</span>}</div><p className="chart-caveat">{result.limitations[0]}</p><div className="card-actions"><button onClick={()=>onOpen('code',result)}><Code2 size={16}/> Show Python Code</button><button onClick={()=>onOpen('interpretation',result)}><BookOpen size={16}/> Data Interpretation</button><button onClick={()=>onOpen('data',result)}><Table2 size={16}/> View Data</button><button onClick={()=>onDownload(result,'data')}><ArrowDownToLine size={16}/> Download</button></div></>:<div className="chart-placeholder empty"><Info size={20}/>{error||'Apply filters to load this analysis.'}</div>}</article>
}

function DateRangeSelection({meta,selected,start,end,onChange,onGrouping}:{meta:DatasetInfo|null;selected:DatasetInfo|null;start:string;end:string;onChange:(start:string,end:string)=>void;onGrouping:(value:'monthly'|'annual')=>void}) {
  if(!meta?.min_date||!meta.max_date)return <p className="panel-muted">Choose a dataset with dated weather observations.</p>
  const min=day(meta.min_date),max=day(meta.max_date),a=day(start||meta.min_date),b=day(end||meta.max_date)
  const preset=(kind:'full'|'12months'|'5years')=>{if(kind==='full'){onChange(meta.min_date!,meta.max_date!);return}const d=new Date(meta.max_date+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-(kind==='12months'?12:60));d.setUTCDate(d.getUTCDate()+1);onChange(iso(Math.max(min,Math.floor(d.getTime()/86400000))),meta.max_date!)}
  const years=Array.from({length:Number(meta.max_date.slice(0,4))-Number(meta.min_date.slice(0,4))+1},(_,i)=>Number(meta.min_date!.slice(0,4))+i)
  return <section className="date-selection"><div className="section-title"><div><span className="eyebrow">DATE RANGE SELECTION</span><h2>Select the observation period</h2></div><span className="helper">Available: {meta.min_date} to {meta.max_date}</span></div><div className="date-presets"><button onClick={()=>preset('full')}>Full Available Period</button><button onClick={()=>preset('12months')} disabled={max-min<364}>Last 12 Available Months</button><button onClick={()=>preset('5years')} disabled={max-min<1825}>Last 5 Available Years</button><button onClick={()=>onGrouping('monthly')}>Monthly Comparison</button><button onClick={()=>onGrouping('annual')}>Annual Comparison</button><label>Year Selection <select value="" onChange={e=>{const year=Number(e.target.value);onChange(iso(Math.max(min,day(year+'-01-01'))),iso(Math.min(max,day(year+'-12-31'))))}}><option value="">Select year</option>{years.map(y=><option key={y} value={y}>{y}</option>)}</select></label></div><div className="date-inputs"><label>Start date<input type="date" min={meta.min_date} max={end||meta.max_date} value={start} onChange={e=>onChange(e.target.value,end)}/></label><label>End date<input type="date" min={start||meta.min_date} max={meta.max_date} value={end} onChange={e=>onChange(start,e.target.value)}/></label></div><div className="range-sliders"><label>Start <input type="range" min={min} max={max} value={a} onChange={e=>onChange(iso(Math.min(Number(e.target.value),b)),end)}/></label><label>End <input type="range" min={min} max={max} value={b} onChange={e=>onChange(start,iso(Math.max(Number(e.target.value),a)))}/></label></div><p className="date-count">{selected?.selected_observations?.toLocaleString()??'—'} loaded observations in this range · {selected?.selected_valid_temperature?.toLocaleString()??'—'} valid temperature · {selected?.selected_valid_rainfall?.toLocaleString()??'—'} valid rainfall. Missing dates are not filled.</p></section>
}

